// Owns which paths are generated, vendored, lockfiles or test fixtures; review-depth and the hygiene sweeps import it, never restate it.

export const LOCKFILES = new Set([
  "package-lock.json", "npm-shrinkwrap.json", "yarn.lock", "pnpm-lock.yaml", "bun.lockb", "Cargo.lock",
  "Gemfile.lock", "poetry.lock", "Pipfile.lock", "composer.lock", "go.sum", "flake.lock",
]);
export const GENERATED_DIRS = new Set(["dist", "build", "vendor", "node_modules"]);
export const GENERATED_NAME = /\.min\.(?:js|css)$|\.map$|\.generated\./;
// Covers Go's "// Code generated … DO NOT EDIT." through DO NOT EDIT.
export const GENERATED_MARKER = /@generated\b|DO NOT EDIT|<auto-generated/;
export const HEAD_LINES = 5;

export function isExcluded(path) {
  const segments = path.split("/");
  const name = segments.pop();
  return LOCKFILES.has(name) || GENERATED_NAME.test(name) || segments.some((s) => GENERATED_DIRS.has(s));
}

const VENDORED_DIRS = new Set(["vendor", "node_modules"]);
const BUILT_DIRS = new Set(["dist", "build"]);
const FIXTURE_DIRS = new Set(["fixtures", "__fixtures__", "testdata"]);

export function exclusionCategory(path, { head = null, attributes = [] } = {}) {
  const segments = path.split("/");
  const name = segments.pop();
  const marked = (attr) => attributes.some((a) => a.attr === attr && matchesAttribute(a.pattern, path));
  if (LOCKFILES.has(name)) return "lockfile";
  if (segments.some((s) => VENDORED_DIRS.has(s)) || marked("vendored")) return "vendored";
  if (segments.some((s) => BUILT_DIRS.has(s)) || GENERATED_NAME.test(name) || marked("generated")
    || (head !== null && GENERATED_MARKER.test(head))) return "generated";
  if (segments.some((s) => FIXTURE_DIRS.has(s))) return "test-fixture";
  return null;
}

const LINGUIST_ATTRS = { "linguist-generated": "generated", "linguist-vendored": "vendored" };

export function linguistAttributes(text) {
  const entries = [];
  for (const line of text.split("\n")) {
    const [pattern, ...tokens] = line.trim().split(/\s+/);
    if (!pattern || pattern.startsWith("#")) continue;
    for (const token of tokens) {
      const [key, value = "true"] = token.split("=");
      if (Object.hasOwn(LINGUIST_ATTRS, key) && value === "true") entries.push({ pattern, attr: LINGUIST_ATTRS[key] });
    }
  }
  return entries;
}

const GLOB_TOKENS = /\*\*\/|\*\*|[*?]|[.+^${}()|[\]\\]/g;
const GLOB_REGEX = { "**/": "(?:.*/)?", "**": ".*", "*": "[^/]*", "?": "[^/]" };

function globToRegExp(glob) {
  return new RegExp(`^${glob.replace(GLOB_TOKENS, (t) => GLOB_REGEX[t] ?? `\\${t}`)}$`);
}

export function matchesAttribute(pattern, path) {
  const directory = pattern.endsWith("/");
  const body = directory ? pattern.slice(0, -1) : pattern;
  if (directory || body.endsWith("/**")) {
    const base = body.endsWith("/**") ? body.slice(0, -3) : body;
    return globToRegExp(`${base}/**`).test(path);
  }
  return globToRegExp(body).test(body.includes("/") ? path : path.slice(path.lastIndexOf("/") + 1));
}
